        variable b_elem : signed(7 downto 0);
    begin
        for i in 0 to 7 loop
            a_elem := signed(a_v(8*i+7 downto 8*i));
            b_elem := signed(b_v(8*i+7 downto 8*i));
            result(i) := a_elem * b_elem;
        end loop;
        return result;
    end function;

    signal products : prod_array_t;
    signal sum_comb : signed(31 downto 0);

begin

    products <= compute_products(a_flat, b_flat);

    sum_comb <= resize(products(0), 32) + resize(products(1), 32) +
                resize(products(2), 32) + resize(products(3), 32) +
                resize(products(4), 32) + resize(products(5), 32) +
                resize(products(6), 32) + resize(products(7), 32);

    process(clk)
    begin
        if rising_edge(clk) then
            if rst = '1' then
                y <= (others => '0');
            elsif en = '1' then
                y <= sum_comb;
            end if;
        end if;
    end process;

end architecture rtl;

