        b_flat : in  std_logic_vector(63 downto 0);
        y      : out signed(31 downto 0)
    );
end entity mac_array8;

architecture rtl of mac_array8 is
    -- Extract signed 8-bit elements from 64-bit flat vectors
    function extract_signed_byte(vec : std_logic_vector(63 downto 0); idx : integer)
        return signed is
        variable byte_val : std_logic_vector(7 downto 0);
    begin
        byte_val := vec(8*idx+7 downto 8*idx);
        return signed(byte_val);
    end function;

    signal y_next : signed(31 downto 0);
    signal prod_sum : signed(31 downto 0);

begin
    -- Compute eight signed 8-bit products and sum them
    process(a_flat, b_flat)
        variable a0, a1, a2, a3, a4, a5, a6, a7 : signed(7 downto 0);
        variable b0, b1, b2, b3, b4, b5, b6, b7 : signed(7 downto 0);
        variable p0, p1, p2, p3, p4, p5, p6, p7 : signed(15 downto 0);
        variable sum : signed(31 downto 0);
    begin
        a0 := extract_signed_byte(a_flat, 0);
        a1 := extract_signed_byte(a_flat, 1);
        a2 := extract_signed_byte(a_flat, 2);
        a3 := extract_signed_byte(a_flat, 3);
        a4 := extract_signed_byte(a_flat, 4);
        a5 := extract_signed_byte(a_flat, 5);
        a6 := extract_signed_byte(a_flat, 6);
        a7 := extract_signed_byte(a_flat, 7);

        b0 := extract_signed_byte(b_flat, 0);
        b1 := extract_signed_byte(b_flat, 1);
        b2 := extract_signed_byte(b_flat, 2);
        b3 := extract_signed_byte(b_flat, 3);
        b4 := extract_signed_byte(b_flat, 4);
        b5 := extract_signed_byte(b_flat, 5);
        b6 := extract_signed_byte(b_flat, 6);
        b7 := extract_signed_byte(b_flat, 7);

        p0 := a0 * b0;
        p1 := a1 * b1;
        p2 := a2 * b2;
        p3 := a3 * b3;
        p4 := a4 * b4;
        p5 := a5 * b5;
        p6 := a6 * b6;
        p7 := a7 * b7;

        sum := resize(p0, 32) + resize(p1, 32) + resize(p2, 32) + resize(p3, 32) +
               resize(p4, 32) + resize(p5, 32) + resize(p6, 32) + resize(p7, 32);

        prod_sum <= sum;
    end process;

    -- Register output with control logic
    process(clk)
    begin
        if rising_edge(clk) then
            if rst = '1' then
                y_next <= (others => '0');
            elsif en = '1' then
                y_next <= prod_sum;
            end if;
        end if;
    end process;

    y <= y_next;

end architecture rtl;

