library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;

entity mac_array8 is
    port (
        clk    : in  std_logic;
        rst    : in  std_logic;
        en     : in  std_logic;
        a_flat : in  std_logic_vector(63 downto 0);
        b_flat : in  std_logic_vector(63 downto 0);
        y      : out signed(31 downto 0)
    );
end entity mac_array8;

architecture rtl of mac_array8 is

    type signed_array is array (0 to 7) of signed(7 downto 0);

    function unpack_signed(data : std_logic_vector(63 downto 0)) return signed_array is
        variable result : signed_array;
    begin
        for i in 0 to 7 loop
            result(i) := signed(data(8*i+7 downto 8*i));
        end loop;
        return result;
    end function;

    signal a_unpacked : signed_array;
    signal b_unpacked : signed_array;

    signal product0 : signed(15 downto 0);
    signal product1 : signed(15 downto 0);
    signal product2 : signed(15 downto 0);
    signal product3 : signed(15 downto 0);
    signal product4 : signed(15 downto 0);
    signal product5 : signed(15 downto 0);
    signal product6 : signed(15 downto 0);
    signal product7 : signed(15 downto 0);

    signal sum_stage1_a : signed(17 downto 0);
    signal sum_stage1_b : signed(17 downto 0);
    signal sum_stage1_c : signed(17 downto 0);
    signal sum_stage1_d : signed(17 downto 0);

    signal sum_stage2_a : signed(18 downto 0);
    signal sum_stage2_b : signed(18 downto 0);

    signal sum_stage3 : signed(19 downto 0);

    signal result_reg : signed(31 downto 0);

begin

    a_unpacked <= unpack_signed(a_flat);
    b_unpacked <= unpack_signed(b_flat);

    product0 <= a_unpacked(0) * b_unpacked(0);
    product1 <= a_unpacked(1) * b_unpacked(1);
    product2 <= a_unpacked(2) * b_unpacked(2);
    product3 <= a_unpacked(3) * b_unpacked(3);
    product4 <= a_unpacked(4) * b_unpacked(4);
    product5 <= a_unpacked(5) * b_unpacked(5);
    product6 <= a_unpacked(6) * b_unpacked(6);
    product7 <= a_unpacked(7) * b_unpacked(7);

    sum_stage1_a <= resize(product0, 18) + resize(product1, 18);
    sum_stage1_b <= resize(product2, 18) + resize(product3, 18);
    sum_stage1_c <= resize(product4, 18) + resize(product5, 18);
    sum_stage1_d <= resize(product6, 18) + resize(product7, 18);

    sum_stage2_a <= resize(sum_stage1_a, 19) + resize(sum_stage1_b, 19);
    sum_stage2_b <= resize(sum_stage1_c, 19) + resize(sum_stage1_d, 19);

    sum_stage3 <= resize(sum_stage2_a, 20) + resize(sum_stage2_b, 20);

    process(clk)
    begin
        if rising_edge(clk) then
            if rst = '1' then
                result_reg <= (others => '0');
            elsif en = '1' then
                result_reg <= resize(sum_stage3, 32);
            end if;
        end if;
    end process;

    y <= result_reg;

end architecture rtl;
